        field_combo.lcr.dlab.next_q <= next_c;
        field_combo.lcr.dlab.load_next <= load_next_c;
    end process;
    process(clk) begin
        if false then -- async reset
            field_storage.lcr.dlab.value <= '0';
        elsif rising_edge(clk) then
            if rst then -- sync reset
                field_storage.lcr.dlab.value <= '0';
            else
                if field_combo.lcr.dlab.load_next then
                    field_storage.lcr.dlab.value <= field_combo.lcr.dlab.next_q;
                end if;
            end if;
        end if;
    end process;
    hwif_out.lcr.dlab.value <= field_storage.lcr.dlab.value;

    -- Field: iurt.mcr.dtr
    process(all)
        variable next_c: std_logic;
        variable load_next_c: std_logic;
    begin
        next_c := field_storage.mcr.dtr.value;
        load_next_c := '0';
        if decoded_reg_strb.mcr and decoded_req_is_wr then -- SW write
            next_c := (field_storage.mcr.dtr.value and not decoded_wr_biten(0)) or (decoded_wr_data(0) and decoded_wr_biten(0));
            load_next_c := '1';
        end if;
        field_combo.mcr.dtr.next_q <= next_c;
        field_combo.mcr.dtr.load_next <= load_next_c;
    end process;
    process(clk) begin
        if false then -- async reset
            field_storage.mcr.dtr.value <= '0';
        elsif rising_edge(clk) then
            if rst then -- sync reset
                field_storage.mcr.dtr.value <= '0';
            else
                if field_combo.mcr.dtr.load_next then
                    field_storage.mcr.dtr.value <= field_combo.mcr.dtr.next_q;
                end if;
            end if;
        end if;
    end process;
    hwif_out.mcr.dtr.value <= field_storage.mcr.dtr.value;

    -- Field: iurt.mcr.rts
    process(all)
        variable next_c: std_logic;
        variable load_next_c: std_logic;
    begin
        next_c := field_storage.mcr.rts.value;
        load_next_c := '0';
        if decoded_reg_strb.mcr and decoded_req_is_wr then -- SW write
            next_c := (field_storage.mcr.rts.value and not decoded_wr_biten(1)) or (decoded_wr_data(1) and decoded_wr_biten(1));
            load_next_c := '1';
        end if;
        field_combo.mcr.rts.next_q <= next_c;
        field_combo.mcr.rts.load_next <= load_next_c;
    end process;
    process(clk) begin
        if false then -- async reset
            field_storage.mcr.rts.value <= '0';
        elsif rising_edge(clk) then
            if rst then -- sync reset
                field_storage.mcr.rts.value <= '0';
            else
                if field_combo.mcr.rts.load_next then
                    field_storage.mcr.rts.value <= field_combo.mcr.rts.next_q;
                end if;
            end if;
        end if;
    end process;
    hwif_out.mcr.rts.value <= field_storage.mcr.rts.value;

    -- Field: iurt.mcr.out1
    process(all)
        variable next_c: std_logic;
        variable load_next_c: std_logic;
    begin
        next_c := field_storage.mcr.out1.value;
        load_next_c := '0';
        if decoded_reg_strb.mcr and decoded_req_is_wr then -- SW write
            next_c := (field_storage.mcr.out1.value and not decoded_wr_biten(2)) or (decoded_wr_data(2) and decoded_wr_biten(2));
            load_next_c := '1';
        end if;
        field_combo.mcr.out1.next_q <= next_c;
        field_combo.mcr.out1.load_next <= load_next_c;
    end process;
    process(clk) begin
        if false then -- async reset
            field_storage.mcr.out1.value <= '0';
        elsif rising_edge(clk) then
            if rst then -- sync reset
                field_storage.mcr.out1.value <= '0';
            else
                if field_combo.mcr.out1.load_next then
                    field_storage.mcr.out1.value <= field_combo.mcr.out1.next_q;
                end if;
            end if;
        end if;
    end process;
    hwif_out.mcr.out1.value <= field_storage.mcr.out1.value;

    -- Field: iurt.mcr.out2
    process(all)
        variable next_c: std_logic;
        variable load_next_c: std_logic;
    begin
        next_c := field_storage.mcr.out2.value;
        load_next_c := '0';
        if decoded_reg_strb.mcr and decoded_req_is_wr then -- SW write
            next_c := (field_storage.mcr.out2.value and not decoded_wr_biten(3)) or (decoded_wr_data(3) and decoded_wr_biten(3));
            load_next_c := '1';
        end if;
        field_combo.mcr.out2.next_q <= next_c;
        field_combo.mcr.out2.load_next <= load_next_c;
    end process;
    process(clk) begin
        if false then -- async reset
            field_storage.mcr.out2.value <= '0';
        elsif rising_edge(clk) then
            if rst then -- sync reset
                field_storage.mcr.out2.value <= '0';
            else
                if field_combo.mcr.out2.load_next then
                    field_storage.mcr.out2.value <= field_combo.mcr.out2.next_q;
                end if;
            end if;
        end if;
    end process;
    hwif_out.mcr.out2.value <= field_storage.mcr.out2.value;

    -- Field: iurt.mcr.loopback
    process(all)
        variable next_c: std_logic;
        variable load_next_c: std_logic;
    begin
        next_c := field_storage.mcr.loopback.value;
        load_next_c := '0';
        if decoded_reg_strb.mcr and decoded_req_is_wr then -- SW write
            next_c := (field_storage.mcr.loopback.value and not decoded_wr_biten(4)) or (decoded_wr_data(4) and decoded_wr_biten(4));
            load_next_c := '1';
        end if;
        field_combo.mcr.loopback.next_q <= next_c;
        field_combo.mcr.loopback.load_next <= load_next_c;
    end process;
    process(clk) begin
        if false then -- async reset
            field_storage.mcr.loopback.value <= '0';
        elsif rising_edge(clk) then
            if rst then -- sync reset
                field_storage.mcr.loopback.value <= '0';
            else
                if field_combo.mcr.loopback.load_next then
                    field_storage.mcr.loopback.value <= field_combo.mcr.loopback.next_q;
                end if;
            end if;
        end if;
    end process;
    hwif_out.mcr.loopback.value <= field_storage.mcr.loopback.value;

    -- Field: iurt.lsr.oe
    process(all)
        variable next_c: std_logic;
        variable load_next_c: std_logic;
    begin
        next_c := field_storage.lsr.oe.value;
        load_next_c := '0';
        if decoded_reg_strb.lsr and not decoded_req_is_wr then -- SW clear on read
            next_c := '0';
            load_next_c := '1';
        elsif hwif_in.lsr.oe.hwset then -- HW Set
            next_c := '1';
            load_next_c := '1';
        end if;
        field_combo.lsr.oe.next_q <= next_c;
        field_combo.lsr.oe.load_next <= load_next_c;
    end process;
    process(clk) begin
        if false then -- async reset
            field_storage.lsr.oe.value <= '0';
        elsif rising_edge(clk) then
            if rst then -- sync reset
                field_storage.lsr.oe.value <= '0';
            else
                if field_combo.lsr.oe.load_next then
                    field_storage.lsr.oe.value <= field_combo.lsr.oe.next_q;
                end if;
            end if;
        end if;
    end process;
    hwif_out.lsr.oe.value <= field_storage.lsr.oe.value;

    -- Field: iurt.scr.data
    process(all)
        variable next_c: std_logic_vector(7 downto 0);
        variable load_next_c: std_logic;
    begin
        next_c := field_storage.scr.data.value;
        load_next_c := '0';
        if decoded_reg_strb.scr and decoded_req_is_wr then -- SW write
            next_c := (field_storage.scr.data.value and not decoded_wr_biten(7 downto 0)) or (decoded_wr_data(7 downto 0) and decoded_wr_biten(7 downto 0));
            load_next_c := '1';
        end if;
        field_combo.scr.data.next_q <= next_c;
        field_combo.scr.data.load_next <= load_next_c;
    end process;
    process(clk) begin
        if false then -- async reset
            field_storage.scr.data.value <= 8x"0";
        elsif rising_edge(clk) then
            if rst then -- sync reset
                field_storage.scr.data.value <= 8x"0";
            else
                if field_combo.scr.data.load_next then
                    field_storage.scr.data.value <= field_combo.scr.data.next_q;
                end if;
            end if;
        end if;
    end process;

    ----------------------------------------------------------------------------
    -- Write response
    ----------------------------------------------------------------------------
    process(all)
        variable wr_ack: std_logic;
    begin
        wr_ack := '0';
        wr_ack := wr_ack or hwif_in.rbr_thr_dll.wr_ack;
        wr_ack := wr_ack or hwif_in.ier_dlm.wr_ack;
        external_wr_ack <= wr_ack;
    end process;
    cpuif_wr_ack <= external_wr_ack or (decoded_req and decoded_req_is_wr and not decoded_req_is_external);
    -- Writes are always granted with no error response
    cpuif_wr_err <= '0';

    ----------------------------------------------------------------------------
    -- Readback
    ----------------------------------------------------------------------------
    process(all)
        variable rd_ack: std_logic;
    begin
        rd_ack := '0';
        rd_ack := rd_ack or hwif_in.rbr_thr_dll.rd_ack;
        rd_ack := rd_ack or hwif_in.ier_dlm.rd_ack;
        readback_external_rd_ack_c <= rd_ack;
    end process;

    readback_external_rd_ack <= readback_external_rd_ack_c;
    -- Hold read mux address to guarantee it is stable throughout any external accesses
    process(clk) begin
        if false then -- async reset
            pending_rd_addr <= (others => '0');
        elsif rising_edge(clk) then
            if rst then -- sync reset
                pending_rd_addr <= (others => '0');
            else
                if decoded_req then
                    pending_rd_addr <= decoded_addr;
                end if;
            end if;
        end if;
    end process;
    rd_mux_addr <= unsigned(decoded_addr) when decoded_req = '1' else unsigned(pending_rd_addr);

    process(all)
        variable readback_data_var : std_logic_vector(31 downto 0);
    begin
        readback_data_var := (others => '0');
        if rd_mux_addr = 16#0# then
            readback_data_var := hwif_in.rbr_thr_dll.rd_data;
        end if;
        if rd_mux_addr = 16#4# then
            readback_data_var := hwif_in.ier_dlm.rd_data;
        end if;
        if rd_mux_addr = 16#8# then
            readback_data_var(0) := hwif_in.iir.no_int.next_q;
            readback_data_var(2 downto 1) := hwif_in.iir.id.next_q;
        end if;
        if rd_mux_addr = 16#C# then
            readback_data_var(1 downto 0) := field_storage.lcr.wls.value;
            readback_data_var(2) := field_storage.lcr.stb.value;
            readback_data_var(3) := field_storage.lcr.pen.value;
            readback_data_var(4) := field_storage.lcr.eps.value;
            readback_data_var(5) := field_storage.lcr.sp.value;
            readback_data_var(6) := field_storage.lcr.bc.value;
            readback_data_var(7) := field_storage.lcr.dlab.value;
        end if;
        if rd_mux_addr = 16#10# then
            readback_data_var(0) := field_storage.mcr.dtr.value;
            readback_data_var(1) := field_storage.mcr.rts.value;
            readback_data_var(2) := field_storage.mcr.out1.value;
            readback_data_var(3) := field_storage.mcr.out2.value;
            readback_data_var(4) := field_storage.mcr.loopback.value;
        end if;
        if rd_mux_addr = 16#14# then
            readback_data_var(0) := hwif_in.lsr.dr.next_q;
            readback_data_var(1) := field_storage.lsr.oe.value;
            readback_data_var(2) := '0';
            readback_data_var(3) := '0';
            readback_data_var(4) := '0';
            readback_data_var(5) := hwif_in.lsr.thre.next_q;
            readback_data_var(6) := hwif_in.lsr.temt.next_q;
        end if;
        if rd_mux_addr = 16#18# then
            readback_data_var(0) := '0';
            readback_data_var(1) := '0';
            readback_data_var(2) := '0';
            readback_data_var(3) := '0';
            readback_data_var(4) := hwif_in.msr.cts.next_q;
            readback_data_var(5) := hwif_in.msr.dsr.next_q;
            readback_data_var(6) := hwif_in.msr.ri.next_q;
            readback_data_var(7) := hwif_in.msr.dcd.next_q;
        end if;
        if rd_mux_addr = 16#1C# then
            readback_data_var(7 downto 0) := field_storage.scr.data.value;
        end if;
        readback_data <= readback_data_var;
        readback_done <= decoded_req and not decoded_req_is_wr and not decoded_req_is_external;
        readback_err <= '0';
    end process;

    external_rd_ack <= readback_external_rd_ack;
    cpuif_rd_ack <= readback_done or readback_external_rd_ack;
    cpuif_rd_data <= readback_data;
    cpuif_rd_err <= readback_err;
end architecture rtl;
